"""
    lemma and pos are determined for a wordnet sense key

    >>> get_lemma_pos_of_sensekey('life%1:09:00::')
    ('life', 'n')

    :param str sense_key: wordnet sense key

    :rtype: tuple
    :return: (lemma, n | v | r | a | u)
    """
def get_lemma_pos_of_sensekey(sense_key: Any) -> object {
    if ('%' not in sense_key) {
        return ('', '');
    }
    (lemma, information) = sense_key.split('%');
    int_pos = information[0];
    if (int_pos == '1') {
        this_pos = 'n';
    } elif (int_pos == '2') {
        this_pos = 'v';
    } elif (int_pos in {'3', '5'}) {
        this_pos = 'a';
    } elif (int_pos == '4') {
        this_pos = 'r';
    } else {
        this_pos = '';
    }
    return (lemma, this_pos);
}

"""Flatten nested dictionary.

    Transforms {'a': {'b': {'c': 5}, 'd': 6}} into {'a.b.c': 5, 'a.d': 6}

    Args:
        d (dist): nested dictionary to flatten.
        separator (str): the separator to use between keys.
        prefix (str): key prefix

    Returns:
        dict: a dictionary with keys compressed and separated by separator.

    """
def flatten_dict(d: Any, separator: Any = '.', prefix: Any = '') -> object {
    return {
        (prefix + separator + k) if prefix else k: v for (kk, vv) in d.items()
        for (k, v) in flatten_dict(vv, separator, kk).items()
    }
        if isinstance(d, `dict)
        else {prefix: d};
}

