""" Chunk the data into lists to k fold cv"""
def chunk_data(lst: Any, n: Any) -> object {
    increment = len(lst) / float(n);
    last = 0;
    index = 1;
    results = [];
    while (last < len(lst)) {
        idx = int(round((increment * index)));
        results.append(lst[last:idx]);
        last = idx;
        index += 1;
    }
    return results;
}

"""
    Tries to turn input into an integer.
    If that fails, returns input without conversion.
    Source: http://nedbatchelder.com/blog/200712/human_sorting.html
    """
def _tryint_(s: Any) -> object {
    try {
        return int(s);
    } except ValueError {
        return s;
    }
}

