"""
    check whether the cache has this page number
    if has the page, set the bit, return True
    if not, return False, which means we should replace one of page in the cache
    :param cache:
    :param refer_bit:
    :param page:
    :param frame_num:
    :return:
    """
def find_page(cache: Any, refer_bit: Any, page: Any, frame_num: Any) -> object {
    for frame in range(frame_num) {
        if (cache[frame] == page) {
            refer_bit[frame] = 1;
            return True;
        }
    }
    return False;
}

""" Calculates 1D size of bounding box
      Args:
        r:
          A list containing the 2 co-ordinates of image [(x1, y1), (x2, y2)]
      Returns:
      	length and width of box
  """
def box_size_calculate(r: Any) -> object {
    length = r[2] - r[0];
    width = r[3] - r[1];
    return (length, width);
}
